    "name": "钠（金属钠）",
    "formula": "Na",
    "category": "单质",
    "hazard": 3,
    "summary": "工业上电解熔融氯化钠（Downs 法）制取金属钠，阴极析出钠，阳极产生氯气。",
    "principle": [
      "2NaCl(熔融) →(电解) 2Na + Cl₂↑",
      "阴极：Na⁺ + e⁻ → Na",
      "阳极：2Cl⁻ − 2e⁻ → Cl₂↑"
    ],
    "reagents": [
      "无水氯化钠",
      "氯化钙（助熔剂，降低熔点）",
      "石墨阳极",
      "铁阴极"
    ],
    "apparatus": [
      "电解槽",
      "直流电源",
      "惰性气氛保护装置",
      "集钠器",
      "通风橱"
    ],
    "steps": [
      "氯化钠与氯化钙按比例混合并充分干燥，装入电解槽。",
      "加热至约 600–650 ℃ 使盐熔融，插入石墨阳极与铁阴极。",
      "通直流电电解；熔融钠密度小而浮在电解质表面，导入集钠器。",
      "钠在矿物油中冷却密封保存，阳极氯气用碱液吸收。"
    ],
    "observation": "阴极区出现银白色液态钠，阳极有黄绿色氯气产生。",
    "conclusion": "活泼金属只能用电解熔融盐的方法制取；钠的密度小于熔融电解质，便于分离收集。",
    "cautions": [
      "钠遇水剧烈反应并放出氢气，可能燃烧爆炸，严禁接触水、酸和卤代烃。",
      "熔融盐温度高、氯气有毒，仅限工业装置或有资质的实验室演示。",
      "金属钠须浸没在矿物油中密封保存，远离火源。",
      "本条目仅用于原理认知，不提供家庭或非专业场所的操作方案。"
    ],
    "tags": [
      "电解",
      "活泼金属",
      "Downs 法",
      "高危"
    ],
    "uses": [
      "钠光灯（黄色光源）",
      "有机合成中的还原剂",
      "制备过氧化钠、氨基钠等",
      "核反应堆导热剂"
    ],
